use crate::aap::caps::kb_read;

struct Node;

/// Bound on `question`, per the node's contract.
const MAX_QUESTION: usize = 512;

/// Placeholder so that `present(knowledge)` holds when the store has no match.
const NO_KNOWLEDGE: &str = "no matching knowledge-base entries";

/// Truncate `s` to at most `max` bytes, cutting only at a char boundary.
/// Being at most 512 bytes also means at most 512 characters.
fn bound(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // The requires-clause already holds; bounding again keeps the
        // ensures-clause true even if the upstream contract is violated.
        let question = bound(&query.query.question, MAX_QUESTION);

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

